 "edits": [
   {"old": "import { mock, describe, expect, test } from 'bun:test'",
    "new": "import { mock, describe, expect, test } from 'bun:test'
import type { BetaUsage } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'"},
   {"old": "function makeUserMessage(text: string) {
  return {
    type: 'user' as const,
    uuid: `test-${Math.random()}`,
    message: { role: 'user' as const, content: text },
  }
}",
    "new": "function makeUserMessage(text: string) {
  return {
    type: 'user' as const,
    uuid: `test-${Math.random()}`,
    message: { role: 'user' as const, content: text },
  }
}

// Rellena los campos de BetaUsage no ejercitados por el test con sus valores neutros.
function makeUsage(overrides: Partial<BetaUsage> = {}): BetaUsage {
  return {
    cache_creation: null,
    cache_creation_input_tokens: 0,
    cache_read_input_tokens: 0,
    fallback_credit: null,
    inference_geo: null,
    input_tokens: 0,
    iterations: null,
    output_tokens: 0,
    output_tokens_details: null,
    server_tool_use: null,
    service_tier: null,
    speed: null,
    ...overrides,
  }
}"},
   {"old": "  test('handles zero values', () => {
    const usage = {
      input_tokens: 0,
      output_tokens: 0,
      cache_creation_input_tokens: 0,
      cache_read_input_tokens: 0,
    }
    expect(getTokenCountFromUsage(usage)).toBe(0)
  })",
    "new": "  test('handles zero values', () => {
    const usage = makeUsage({
      input_tokens: 0,
      output_tokens: 0,
      cache_creation_input_tokens: 0,
      cache_read_input_tokens: 0,
    })
    expect(getTokenCountFromUsage(usage)).toBe(0)
  })"}
 ],
 "patterns": [
   {"patron": "partial-usage-literal-missing-betausage-fields",
    "senal_del_verificador": "TS2345:.*not assignable to parameter of type 'BetaUsage'",
    "fix_generico": "El literal del test sólo declara los campos que ejercita (input_tokens, output_tokens, cache_*), pero BetaUsage exige también cache_creation, fallback_credit, inference_geo, iterations, output_tokens_details, server_tool_use, service_tier y speed. En vez de castear (prohibido) o completar el literal a mano en cada sitio, se define una función local `makeUsage(overrides: Partial<BetaUsage>): BetaUsage` que rellena esos campos con su valor neutro (null/0) y aplica los overrides del test; cada literal parcial pasa a construirse con `makeUsage({...})`.",
